#include "teya/editor/EditorContext.h"
namespace teya::editor { SimulationMode EditorContext::simulationMode()const{return mode_;} void EditorContext::play(){mode_=SimulationMode::Playing;} void EditorContext::pause(){mode_=SimulationMode::Paused;} void EditorContext::step(){if(mode_!=SimulationMode::Playing)mode_=SimulationMode::StepRequested;} bool EditorContext::consumeSimulationStep(){if(mode_==SimulationMode::Playing)return true;if(mode_==SimulationMode::StepRequested){mode_=SimulationMode::Paused;return true;}return false;} bool EditorContext::allowsGameInput(const InputGateState&s){const bool active=s.simulation==SimulationMode::Playing||s.simulation==SimulationMode::StepRequested; return active&&(s.gameViewFocused||s.captureEnabled)&&!s.modalOpen&&(!s.keyboardRequired||!s.wantKeyboard)&&(!s.mouseRequired||!s.wantMouse);} }
